';
UPDATE `ai_model_config` SET `remark` = 'iFlytek streaming speech recognition setup:
1. Log in to the iFlytek Open Platform https://www.xfyun.cn/
2. Create a speech recognition application to obtain the APPID, APISecret and APIKey
3. Parameters:
   - app_id: application ID, obtained after creating an application on the iFlytek Open Platform
   - api_key: API key, used for API authentication
   - api_secret: API secret, used to generate signatures
   - domain: recognition domain; default slm (intelligent speech transcription)
   - language: recognition language; default zh_cn (Chinese)
   - accent: dialect; default mandarin (Mandarin), also supports cantonese (Cantonese), etc.
   - dwa: dynamic correction; default wpgs (dynamic correction enabled)
   - output_dir: output directory for audio files; default tmp/
4. Supports real-time streaming recognition, suitable for real-time voice interaction
5. Supports recognition of multiple dialects and languages
' WHERE id = 'ASR_XunfeiStream' AND `remark` = '讯飞流式语音识别配置说明：
1. 登录讯飞开放平台 https://www.xfyun.cn/
2. 创建语音识别应用获取APPID、APISecret、APIKey
3. 参数说明：
   - app_id: 应用ID，在讯飞开放平台创建应用后获得
   - api_key: API密钥，用于接口鉴权
   - api_secret: API密钥，用于生成签名
   - domain: 识别领域，默认slm（智能化语音转写）
   - language: 识别语言，默认zh_cn（中文）
   - accent: 方言类型，默认mandarin（普通话），支持cantonese（粤语）等
   - dwa: 动态修正，默认wpgs（开启动态修正）
   - output_dir: 音频文件输出目录，默认tmp/
4. 支持实时流式识别，适用于实时语音交互场景
5. 支持多种方言和语言识别
';
UPDATE `ai_model_config` SET `remark` = 'Function-call intent recognition setup:
1. Uses the LLM''s function_call capability for intent recognition
2. The selected LLM must support function_call
