UPDATE `ai_model_config` SET `remark` = 'LLM intent recognition setup:
1. Uses a separate LLM for intent recognition
2. Uses the selected_module.LLM model by default
3. Can be configured to use a separate LLM (e.g. the free ChatGLMLLM)
4. Highly versatile, but adds processing time
Configuration:
1. Specify the LLM model to use in the llm field
2. If not specified, the selected_module.LLM model is used' WHERE id = 'Intent_intent_llm' AND `remark` = 'LLM意图识别配置说明：
