UPDATE `ai_model_config` SET `remark` = 'iFlytek Spark LLM setup:
1. Log in to the iFlytek Open Platform https://www.xfyun.cn/. Each model has its own api_password; when changing models, check the api_password for that model
2. Create a Spark LLM application to obtain the API Password
3. Parameters:
   - api_password: API Password, obtained after creating an application on the iFlytek Open Platform
   - model_name: model name; supports generalv3.5, generalv3 and other versions
   - base_url: API address; default https://spark-api-open.xf-yun.com/v1
   - temperature: temperature, controls generation randomness, range 0-1, default 0.5
   - max_tokens: maximum number of output tokens, default 2048
   - top_p: nucleus sampling parameter, controls vocabulary diversity, default 1.0
   - frequency_penalty: frequency penalty, reduces repetitive content, default 0.0
4. Each model has its own api_password; when changing models, check the api_password for that model.
' WHERE id = 'LLM_XunfeiSparkLLM' AND `remark` = '讯飞星火认知大模型配置说明：
